INSERT INTO mission_banned (title, reason) VALUES
('책 한 권 읽기 · 독후감 쓰기','원래 즐거운 일에 보상을 붙이면 보상이 끊길 때 전보다 덜 읽는다'),
('단원평가 백 점 맞기','결과에 보상을 걸면 거짓말·부정행위가 크게 는다'),
('형제와 안 싸우기','판정이 주관적이라 억울함이 생기고 시스템을 불신한다'),
('피아노·미술 삼십 분 연습','예술이 도장 받으려는 노동이 된다'),
('초1~4가 혼자 불 쓰기','저학년은 화상·화재 위험이 크다. 고학년은 「불을 써요」 표시를 달고 부모가 고르게 한다'),
('락스·세제로 청소하기','호흡기와 피부에 해로운 물질에 노출된다'),
('방 완벽하게 청소하기','「완벽」의 기준이 없어 좌절하고 결국 부모가 다시 한다'),
('부모님 말씀에 무조건 따르기','고학년의 자율성을 정면으로 누른다'),
('밥 남기지 않고 다 먹기','그날 컨디션을 무시해 식사에 강박이 생긴다'),
('친구에게 무조건 양보하기','「착한 일」의 기준이 어른 기분에 따라 달라진다'),
('영어 단어 하루 오십 개 외우기','난이도가 높아 실패가 쌓이면 아예 안 하게 된다'),
('며칠 연속 달성하기(스트릭)','끊기는 게 아까워 안 한 날도 눌러버린다'),
('형제보다 도장 많이 모으기','미션 난이도가 달라 개수 비교가 성립하지 않는다'),
('초1~4가 칼 쓰기','저학년은 손을 다칠 위험이 크다. 고학년은 부모 판단에 맡긴다'),
('무거운 쓰레기봉투 옮기기','몸에 무리가 가고 바깥 이동에 위험이 따른다'),
('사람들 앞에서 발표 잘하기','내성적인 아이에게 큰 불안을 주고 판정도 주관적이다'),
('울음 일 분 안에 그치기','감정을 억누르게 만들어 오히려 조절이 어려워진다'),
('하루 종일 화 안 내기','자연스러운 감정을 부정하는 비현실적인 목표'),
('오답 하나 없이 다 맞기','틀리면서 배우는 기회를 없애고 완벽주의를 만든다'),
('종교 활동 참석하기','믿음의 영역에 보상을 붙이면 스스로 받아들이는 것을 막는다');
